using EduMark.Application.Contracts;
using EduMark.Application.Interfaces;
using EduMark.Domain.Entities;
using EduMark.Infrastructure.Persistence;
using Microsoft.EntityFrameworkCore;
namespace EduMark.Infrastructure.Services;
public sealed class CourseService(EduMarkDbContext db) : ICourseService
{ public async Task<IReadOnlyList<CourseResponse>> GetAllAsync(bool publishedOnly, CancellationToken ct) { var q = db.Courses.AsNoTracking().AsQueryable(); if (publishedOnly) q = q.Where(x => x.IsPublished); return await q.OrderByDescending(x => x.CreatedAtUtc).Select(x => ToResponse(x)).ToListAsync(ct); } public Task<CourseResponse?> GetByIdAsync(Guid id, CancellationToken ct) => db.Courses.AsNoTracking().Where(x => x.Id == id).Select(x => ToResponse(x)).FirstOrDefaultAsync(ct); public async Task<CourseResponse> CreateAsync(CreateCourseRequest r, CancellationToken ct) { var c = new Course { Title = r.Title.Trim(), Description = r.Description.Trim(), Price = r.Price, IsPublished = r.IsPublished }; c.Slug = await UniqueSlug(c.Title, null, ct); db.Courses.Add(c); await db.SaveChangesAsync(ct); return ToResponse(c); } public async Task<CourseResponse?> UpdateAsync(Guid id, UpdateCourseRequest r, CancellationToken ct) { var c = await db.Courses.FindAsync([id], ct); if (c is null) return null; c.Title = r.Title.Trim(); c.Description = r.Description.Trim(); c.Price = r.Price; c.IsPublished = r.IsPublished; c.Slug = await UniqueSlug(c.Title, id, ct); await db.SaveChangesAsync(ct); return ToResponse(c); } public async Task<bool> DeleteAsync(Guid id, CancellationToken ct) { var c = await db.Courses.FindAsync([id], ct); if (c is null) return false; db.Courses.Remove(c); await db.SaveChangesAsync(ct); return true; } private async Task<string> UniqueSlug(string title, Guid? id, CancellationToken ct) { var b = string.Concat(title.ToLowerInvariant().Select(c => char.IsLetterOrDigit(c) ? c : '-')).Trim('-'); if (string.IsNullOrWhiteSpace(b)) b = "course"; var slug = b; var n = 2; while (await db.Courses.AnyAsync(x => x.Slug == slug && x.Id != id, ct)) slug = $"{b}-{n++}"; return slug; } private static CourseResponse ToResponse(Course x) => new(x.Id, x.Title, x.Slug, x.Description, x.Price, x.IsPublished, x.CreatedAtUtc); }
